/* ===== Error helpers ===== */
static int cmdline_error_no_banner(const char *msg1, const char *msg2)
{
    fputc('\n', stderr);
    fputc('\n', stderr);
    fputs("Command Line Error:\n", stderr);
    fputs(msg1, stderr);
    fputc('\n', stderr);
    if (msg2) {
        fputs(msg2, stderr);
        fputc('\n', stderr);
    }
    fflush(stderr);
    return EXIT_CMDLINE;
}

static int cmdline_error_with_banner(const char *msg1, const char *msg2)
{
    write_banner();
    fputc('\n', stderr);
    fputc('\n', stderr);
    fputs("Command Line Error:\n", stderr);
    fputs(msg1, stderr);
    fputc('\n', stderr);
    if (msg2) {
        fputs(msg2, stderr);
        fputc('\n', stderr);
    }
    fflush(stderr);
    return EXIT_CMDLINE;
}

/* ===== Case-insensitive compare ===== */
static int ci_eq(const char *a, const char *b)
{
    while (*a && *b) {
        if (tolower((unsigned char)*a) != tolower((unsigned char)*b))
            return 0;
        a++; b++;
    }
    return *a == 0 && *b == 0;
}

static int is_help_switch(const char *arg)
{
    /* Accept -h (any case, 1 char), -?, --help (any case). */
    if (arg[0] != '-') return 0;
    if (arg[1] == '?' && arg[2] == 0) return 1;
    if ((arg[1] == 'h' || arg[1] == 'H') && arg[2] == 0) return 1;
    if (arg[1] == '-' && ci_eq(arg + 2, "help")) return 1;
    return 0;
}

/* ===== Switch definitions =====
 *
 * Each known switch has a prefix (after the leading '-') and a "postfix
 * spec" describing what, if anything, may follow.  We only need enough
 * fidelity to reproduce the error messages the real 7za produces.
 *
 * Postfix kinds (letters are just mnemonics):
 *   NONE    : no postfix allowed
 *   MINUS   : optional trailing '-'
 *   CHARS   : must be followed by exactly one char from a supplied set
 *   STRING  : followed by an arbitrary (possibly empty) string
 *   CHARSET : a complex CHARS followed by optional extras; used for
 *             switches like -ai where "r[-|0]m[-|2]w[-]" precede a
 *             required {@file|!wildcard} tail.
 *   FULL    : pattern is complex; fall through to generic handling.
 */
enum post_kind {
    P_NONE,     /* no chars allowed after prefix (longer ⇒ "Too long switch") */
    P_MINUS,    /* optional single '-' (longer/other ⇒ "Too long switch") */
    P_CHAR_SET, /* exactly one char from a set (empty ⇒ Too short; other ⇒ bad postfix) */
    P_STRING,   /* arbitrary text follows (empty ⇒ Too short if required) */
    P_STRING_OPT,/* arbitrary text, empty permitted */
    P_INCEXC,    /* -ai/-ax/-i/-x style */
    P_UPDATE,    /* -u... */
    P_VOLUME,    /* -v... */
    P_BS,        /* -bs{o|e|p}{0|1|2} */
    P_BB         /* -bb[0-3] */
};

struct switch_def {
    const char *prefix;
    enum post_kind kind;
    const char *valid_chars; /* for P_CHAR_SET */
    int require_string;      /* for P_STRING: 1 = required, 0 = optional */
};

/* Order matters: longer prefixes must be checked before their shorter
 * relatives.  A linear scan with "best (longest) match wins" handles this. */
static const struct switch_def SWITCHES[] = {
    {"ai",   P_INCEXC,    NULL, 0},
    {"ax",   P_INCEXC,    NULL, 0},
    {"ao",   P_CHAR_SET,  "astu", 0},
    {"an",   P_NONE,      NULL, 0},
    {"bb",   P_BB,        NULL, 0},
    {"bd",   P_NONE,      NULL, 0},
    {"bs",   P_BS,        NULL, 0},
    {"bt",   P_NONE,      NULL, 0},
    {"i",    P_INCEXC,    NULL, 0},
    {"mmt",  P_STRING,    NULL, 0},
    {"mx",   P_STRING,    NULL, 0},
    {"m",    P_STRING,    NULL, 1},
    {"o",    P_STRING,    NULL, 1},
    {"p",    P_STRING_OPT,NULL, 0},
    {"r",    P_MINUS,     NULL, 0},
    {"sa",   P_CHAR_SET,  "aes", 0},
    {"scrc", P_STRING_OPT,NULL, 0},
    {"scc",  P_STRING,    NULL, 1},
    {"scs",  P_STRING_OPT,NULL, 0},
    {"sdel", P_NONE,      NULL, 0},
    {"seml", P_STRING_OPT,NULL, 0},
    {"sfx",  P_STRING_OPT,NULL, 0},
    {"si",   P_STRING_OPT,NULL, 0},
    {"slp",  P_NONE,      NULL, 0},
    {"slt",  P_NONE,      NULL, 0},
    {"snh",  P_MINUS,     NULL, 0},
    {"snl",  P_MINUS,     NULL, 0},
    {"sni",  P_MINUS,     NULL, 0},
    {"sns",  P_MINUS,     NULL, 0},
    {"so",   P_NONE,      NULL, 0},
    {"spd",  P_MINUS,     NULL, 0},
    {"spe",  P_MINUS,     NULL, 0},
    {"spf",  P_STRING_OPT,NULL, 0},
    {"ssc",  P_MINUS,     NULL, 0},
    {"sse",  P_NONE,      NULL, 0},
    {"ssp",  P_NONE,      NULL, 0},
    {"ssw",  P_NONE,      NULL, 0},
    {"stl",  P_NONE,      NULL, 0},
    {"stm",  P_STRING,    NULL, 1},
    {"stx",  P_STRING,    NULL, 1},
    {"t",    P_STRING,    NULL, 1},
    {"u",    P_UPDATE,    NULL, 0},
    {"v",    P_VOLUME,    NULL, 0},
    {"w",    P_STRING_OPT,NULL, 0},
    {"x",    P_INCEXC,    NULL, 0},
    {"y",    P_NONE,      NULL, 0},
    {NULL,   P_NONE,      NULL, 0}
};

/* Find the best (longest) matching switch definition for `body` (the text
 * after the leading '-').  Returns NULL if nothing matches. */
static const struct switch_def *find_switch(const char *body)
{
    const struct switch_def *best = NULL;
    size_t best_len = 0;
    for (const struct switch_def *s = SWITCHES; s->prefix; s++) {
        size_t n = strlen(s->prefix);
        if (strncmp(body, s->prefix, n) == 0 && n > best_len) {
            best = s;
            best_len = n;
        }
    }
    return best;
}

/* Parse the tail of an include/exclude switch: "[r[-|0]][m[-|2]][w[-]]"
 * followed by a required "@file" or "!wildcard".  Returns:
 *   0  : OK
 *   1  : "Too short switch"
 *   2  : "Incorrect switch postfix"
 *   3  : "Too long switch" (unused here)
 */
static int parse_incexc(const char *tail)
{
    const char *p = tail;
    /* r[-|0] */
    if (*p == 'r') {
        p++;
        if (*p == '-' || *p == '0') p++;
    }
    /* m[-|2] */
    if (*p == 'm') {
        p++;
        if (*p == '-' || *p == '2') p++;
    }
    /* w[-] */
    if (*p == 'w') {
        p++;
        if (*p == '-') p++;
    }
    if (*p == 0) return 1; /* need @file or !wildcard */
    if (*p != '@' && *p != '!') return 2;
    /* rest is arbitrary */
    return 0;
}

static int parse_update(const char *tail)
{
    const char *p = tail;
    if (*p == '-') p++;
    while (*p) {
        if (*p == 'p' || *p == 'q' || *p == 'r' || *p == 'x' ||
            *p == 'y' || *p == 'z') {
            p++;
            /* accept one optional digit-ish char */
            while (*p && *p != '!' && !(*p == 'p' || *p == 'q' || *p == 'r' ||
                   *p == 'x' || *p == 'y' || *p == 'z'))
                p++;
        } else if (*p == '!') {
            /* rest is new archive name */
            return 0;
        } else {
            return 2;
        }
    }
    return 0;
}

static int parse_volume(const char *tail)
{
    if (!*tail) return 1;
    /* Must contain digits; last char may be b|k|m|g. */
    const char *p = tail;
    while (*p && isdigit((unsigned char)*p)) p++;
    if (*p) {
        if (p[1] != 0) return 2;
        char c = (char)tolower((unsigned char)*p);
        if (c != 'b' && c != 'k' && c != 'm' && c != 'g') return 2;
    }
    if (p == tail) return 2;
    return 0;
}

static int parse_bs(const char *tail)
{
    if (!*tail) return 1;
    if (!tail[1]) return 1;
    if (tail[2] != 0) return 3;
    char a = tail[0], b = tail[1];
    if (a != 'o' && a != 'e' && a != 'p') return 2;
    if (b != '0' && b != '1' && b != '2') return 2;
    return 0;
}

static int parse_bb(const char *tail)
{
    if (!*tail) return 0;
    if (tail[1] != 0) return 3;
    if (*tail < '0' || *tail > '3') return 2;
    return 0;
}

/* Parse a single switch (argv entry starts with '-' and is not "--").
 * Returns 0 on success.  On error writes the appropriate cmd-line error
 * to stderr (no banner) and returns the error exit code (7).
 */
static int parse_switch(const char *arg)
{
    const char *body = arg + 1;
    if (*body == 0) {
        /* Bare "-" */
        cmdline_error_no_banner("Unknown switch:", arg);
        return EXIT_CMDLINE;
    }

    /* Long form "--foo" (other than "--" which is handled by the caller). */
    if (body[0] == '-') {
        cmdline_error_no_banner("Unknown switch:", arg);
        return EXIT_CMDLINE;
    }

    const struct switch_def *s = find_switch(body);
    if (!s) {
        cmdline_error_no_banner("Unknown switch:", arg);
        return EXIT_CMDLINE;
    }

    const char *tail = body + strlen(s->prefix);

    switch (s->kind) {
    case P_NONE:
        if (*tail) {
            cmdline_error_no_banner("Too long switch:", arg);
            return EXIT_CMDLINE;
        }
        break;
    case P_MINUS:
        if (*tail == 0) break;
        if (tail[0] == '-' && tail[1] == 0) break;
        /* Some -r variants also take '0' */
        if (strcmp(s->prefix, "r") == 0 && tail[0] == '0' && tail[1] == 0)
            break;
        cmdline_error_no_banner("Too long switch:", arg);
        return EXIT_CMDLINE;
    case P_CHAR_SET:
        if (*tail == 0) {
            cmdline_error_no_banner("Too short switch:", arg);
            return EXIT_CMDLINE;
        }
        if (tail[1] != 0) {
            cmdline_error_no_banner("Too long switch:", arg);
            return EXIT_CMDLINE;
        }
        if (!strchr(s->valid_chars, *tail)) {
            cmdline_error_no_banner("Incorrect switch postfix:", arg);
            return EXIT_CMDLINE;
        }
        break;
    case P_STRING:
        if (*tail == 0 && s->require_string) {
            cmdline_error_no_banner("Too short switch:", arg);
            return EXIT_CMDLINE;
        }
        break;
    case P_STRING_OPT:
        /* anything goes */
        break;
    case P_INCEXC: {
        int r = parse_incexc(tail);
        if (r == 1) {
            cmdline_error_no_banner("Too short switch:", arg);
            return EXIT_CMDLINE;
        } else if (r == 2) {
            cmdline_error_no_banner("Incorrect switch postfix:", arg);
            return EXIT_CMDLINE;
        }
        break;
    }
    case P_UPDATE: {
        int r = parse_update(tail);
        if (r == 2) {
            cmdline_error_no_banner("Incorrect switch postfix:", arg);
            return EXIT_CMDLINE;
        }
        break;
    }
    case P_VOLUME: {
        int r = parse_volume(tail);
        if (r == 1) {
            cmdline_error_no_banner("Too short switch:", arg);
            return EXIT_CMDLINE;
        } else if (r == 2) {
            cmdline_error_no_banner("Incorrect switch postfix:", arg);
            return EXIT_CMDLINE;
        }
        break;
    }
    case P_BS: {
        int r = parse_bs(tail);
        if (r == 1) {
            cmdline_error_no_banner("Too short switch:", arg);
            return EXIT_CMDLINE;
        } else if (r == 2) {
            cmdline_error_no_banner("Incorrect switch postfix:", arg);
            return EXIT_CMDLINE;
        } else if (r == 3) {
            cmdline_error_no_banner("Too long switch:", arg);
            return EXIT_CMDLINE;
        }
        break;
    }
    case P_BB: {
        int r = parse_bb(tail);
        if (r == 2) {
            cmdline_error_no_banner("Incorrect switch postfix:", arg);
            return EXIT_CMDLINE;
        } else if (r == 3) {
            cmdline_error_no_banner("Too long switch:", arg);
            return EXIT_CMDLINE;
        }
        break;
    }
    }

    /* Extra heuristic: reject "too long switch" for one-char boolean
     * switches like -y where a trailing char slipped through other checks. */
    if (s->kind == P_NONE && strlen(arg) > 1 + strlen(s->prefix)) {
        cmdline_error_no_banner("Too long switch:", arg);
        return EXIT_CMDLINE;
    }

    return 0;
}

/* ===== Commands ===== */
static int is_known_command(const char *cmd)
{
    static const char *cmds[] = {
        "a", "b", "d", "e", "h", "i", "l", "rn", "t", "u", "x", NULL
    };
    for (int i = 0; cmds[i]; i++)
        if (strcmp(cmds[i], cmd) == 0) return 1;
    return 0;
}

static int command_needs_archive(const char *cmd)
{
    /* b, i, h do not require an archive argument. */
    if (strcmp(cmd, "b") == 0) return 0;
    if (strcmp(cmd, "i") == 0) return 0;
    if (strcmp(cmd, "h") == 0) return 0;
    return 1;
}

/* ===== System ERROR printers (exit 2) ===== */
static int fatal_no_such_file(const char *path)
{
    fputc('\n', stdout);
    fprintf(stderr, "ERROR: errno=%d : %s\n", ENOENT, strerror(ENOENT));
    fprintf(stderr, "%s\n", path);
    fputs("\n\n\n", stdout);
    fputs("System ERROR:\n", stderr);
    fprintf(stderr, "errno=%d : %s\n", ENOENT, strerror(ENOENT));
    fflush(stdout);
    fflush(stderr);
    return EXIT_FATAL;
}

/* ===== Main ===== */
int main(int argc, char **argv)
{
    /* Respect POSIX locale default; setlocale(LC_CTYPE, "") picks up env. */
    setlocale(LC_ALL, "");

    /* First pass: look for help switches before any error; they override
     * everything else that comes before them (like "a -h"). */
    int saw_dd = 0;
    for (int i = 1; i < argc; i++) {
        if (!saw_dd) {
            if (strcmp(argv[i], "--") == 0) { saw_dd = 1; continue; }
            if (is_help_switch(argv[i])) {
                write_banner();
                write_usage();
                return EXIT_OK;
            }
        }
    }

    /* No args at all ⇒ same as help. */
    if (argc < 2) {
        write_banner();
        write_usage();
        return EXIT_OK;
    }

    /* Second pass: separate switches from positionals, detect duplicates. */
    /* Track if each switch prefix has been seen. */
    unsigned seen[256] = {0};
    saw_dd = 0;
    const char *positionals[argc];
    int npos = 0;

    for (int i = 1; i < argc; i++) {
        const char *a = argv[i];
        if (!saw_dd && strcmp(a, "--") == 0) { saw_dd = 1; continue; }
        if (!saw_dd && a[0] == '-') {
            int rc = parse_switch(a);
            if (rc) return rc;
            /* Track "multiple instances" only for -y (the one switch we saw
             * the original executable reject as duplicate). */
            if (strcmp(a, "-y") == 0) {
                if (seen['y']) {
                    return cmdline_error_no_banner("Multiple instances for switch:", a);
                }
                seen['y'] = 1;
            }
            continue;
        }
        positionals[npos++] = a;
    }

    /* Now process the positionals: first is the command, next is archive. */
    if (npos == 0) {
        return cmdline_error_with_banner("The command must be specified", NULL);
    }

    const char *cmd = positionals[0];
    if (!is_known_command(cmd)) {
        return cmdline_error_with_banner("Unsupported command:", cmd);
    }

    if (command_needs_archive(cmd) && npos < 2) {
        return cmdline_error_with_banner("Cannot find archive name", NULL);
    }

    /* Print banner now that parsing looks OK. */
    write_banner();

    /* At this point a real 7-Zip would execute the command.  This partial
     * reimplementation only models the "archive file does not exist" path,
     * which is the most common user-visible outcome of feeding a fresh
     * pathname to extract/test/list commands. */
    if (command_needs_archive(cmd)) {
        const char *arch = positionals[1];
        if (access(arch, F_OK) != 0) {
            return fatal_no_such_file(arch);
        }
    }

    /* Unsupported command paths: we have no archive engine, but we must
     * not silently succeed either.  Return EXIT_FATAL with a generic
     * system error to stay safe. */
    fputs("System ERROR:\nUnsupported\n", stderr);
    return EXIT_FATAL;
}
