#define EXIT_CMDLINE   7

/* ===== Stream helpers ===== */
static void write_banner(void)
{
    /* Leading blank line, banner, environment line, trailing blank line. */
    long threads = sysconf(_SC_NPROCESSORS_ONLN);
    if (threads < 1) threads = 1;

    long open_max;
    struct rlimit rl;
    if (getrlimit(RLIMIT_NOFILE, &rl) == 0 && rl.rlim_cur != RLIM_INFINITY) {
        open_max = (long)rl.rlim_cur;
    } else {
        open_max = sysconf(_SC_OPEN_MAX);
        if (open_max < 0) open_max = 1024;
    }

    /* Locale string: 7-Zip uses setlocale(LC_CTYPE, "") to probe nl_langinfo
     * and picks the codeset.  On modern glibc with no locale variables the
     * codeset is "UTF-8" and the name is reported as "C.UTF-8". */
    const char *codeset = nl_langinfo(CODESET);
    if (!codeset || !*codeset) codeset = "UTF-8";

    /* Compose a locale name.  For POSIX/C/C.UTF-8, always show C.UTF-8 when
     * the codeset is UTF-8, otherwise show the bare codeset. */
    char locbuf[64];
    if (strcmp(codeset, "UTF-8") == 0 || strcmp(codeset, "utf8") == 0 ||
        strcmp(codeset, "UTF8") == 0)
        snprintf(locbuf, sizeof(locbuf), "C.UTF-8");
    else
        snprintf(locbuf, sizeof(locbuf), "%s", codeset);

    fputc('\n', stdout);
    fputs("7-Zip (a) 26.00 (x64) : Copyright (c) 1999-2026 Igor Pavlov : 2026-02-12\n", stdout);
    fprintf(stdout, " 64-bit locale=%s Threads:%ld OPEN_MAX:%ld\n",
            locbuf, threads, open_max);
    fputc('\n', stdout);
    fflush(stdout);
}

