/*
 * 7-Zip compatible command-line driver (partial reimplementation).
 *
 * This binary reproduces the observable command-line behaviour of the 7za
 * front-end: the banner, the usage help, and the switch/command parser
 * error messages.  It does *not* implement any archive engine, so actual
 * archive operations cannot succeed; they fail with the same style of
 * "System ERROR" messages the real tool would emit for a missing file.
 */

#define _GNU_SOURCE
#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <locale.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <unistd.h>

/* Exit codes used by 7-Zip. */
#define EXIT_OK       0
#define EXIT_WARNING  1
#define EXIT_FATAL    2
#define EXIT_CMDLINE  7

/* --------------------------------------------------------------------- */
/* Banner                                                                */
/* --------------------------------------------------------------------- */

static long query_threads(void)
{
    long n = sysconf(_SC_NPROCESSORS_ONLN);
    return (n < 1) ? 1 : n;
}

static long query_open_max(void)
{
    struct rlimit rl;
    if (getrlimit(RLIMIT_NOFILE, &rl) == 0 && rl.rlim_cur != RLIM_INFINITY)
        return (long)rl.rlim_cur;
    long n = sysconf(_SC_OPEN_MAX);
    return (n < 0) ? 1024 : n;
}

