    if ((arg[1] == 'h' || arg[1] == 'H') && arg[2] == 0) return 1;
    if (arg[1] == '?' && arg[2] == 0) return 1;
    if (arg[1] == '-' && ci_eq(arg + 2, "help")) return 1;
    return 0;
}

/* --------------------------------------------------------------------- */
/* Switch grammar                                                        */
/*                                                                       */
/* Every known switch has a prefix, optionally followed by a postfix     */
/* pattern.  The matcher is case-insensitive on the prefix (matches the  */
/* reference behaviour where "-V" is treated like "-v").                 */
/* --------------------------------------------------------------------- */

enum post_kind {
    P_NONE,       /* no postfix allowed */
    P_MINUS,      /* optional single '-' */
    P_MINUS_ZERO, /* optional '-' or '0' (used for -r) */
    P_CHAR_SET,   /* exactly one char from valid_chars */
    P_STRING_REQ, /* any non-empty string */
    P_STRING_OPT, /* any string, empty permitted */
    P_INCEXC,     /* -ai/-ax/-i/-x grammar */
    P_UPDATE,     /* -u... */
    P_VOLUME,     /* -v{Size}[b|k|m|g] */
    P_BS,         /* -bs{oep}{012} */
    P_BB,         /* -bb[0-3] */
    P_SCC,        /* -scc{UTF-8|WIN|DOS} (required tail) */
    P_SCS         /* -scs{...} (optional tail) */
};

struct switch_def {
    const char *prefix;
    enum post_kind kind;
    const char *valid_chars;
};

/* Longer prefixes first so the linear scan finds them before shorter
 * ambiguous ones.  The matcher uses best-match-wins regardless, but keeping
 * the table sorted aids readability. */
static const struct switch_def SWITCHES[] = {
    {"mmt",  P_STRING_OPT, NULL},
    {"mx",   P_STRING_OPT, NULL},
    {"scrc", P_STRING_OPT, NULL},
    {"sdel", P_NONE,       NULL},
    {"seml", P_STRING_OPT, NULL},
    {"sfx",  P_STRING_OPT, NULL},
    {"slp",  P_NONE,       NULL},
    {"slt",  P_NONE,       NULL},
    {"snh",  P_MINUS,      NULL},
    {"snl",  P_MINUS,      NULL},
    {"sni",  P_MINUS,      NULL},
    {"sns",  P_MINUS,      NULL},
    {"spd",  P_MINUS,      NULL},
    {"spe",  P_MINUS,      NULL},
    {"spf",  P_STRING_OPT, NULL},
    {"ssc",  P_MINUS,      NULL},
    {"sse",  P_NONE,       NULL},
    {"ssp",  P_NONE,       NULL},
    {"ssw",  P_NONE,       NULL},
    {"stl",  P_NONE,       NULL},
    {"stm",  P_STRING_REQ, NULL},
    {"stx",  P_STRING_REQ, NULL},
    {"scc",  P_SCC,        NULL},
    {"scs",  P_SCS,        NULL},
    {"ai",   P_INCEXC,     NULL},
    {"ax",   P_INCEXC,     NULL},
    {"ao",   P_CHAR_SET,   "astu"},
    {"an",   P_NONE,       NULL},
    {"bb",   P_BB,         NULL},
    {"bd",   P_NONE,       NULL},
    {"bs",   P_BS,         NULL},
    {"bt",   P_NONE,       NULL},
    {"sa",   P_CHAR_SET,   "aes"},
    {"si",   P_STRING_OPT, NULL},
    {"so",   P_NONE,       NULL},
    {"i",    P_INCEXC,     NULL},
    {"m",    P_STRING_REQ, NULL},
    {"o",    P_STRING_REQ, NULL},
    {"p",    P_STRING_OPT, NULL},
    {"r",    P_MINUS_ZERO, NULL},
    {"t",    P_STRING_REQ, NULL},
    {"u",    P_UPDATE,     NULL},
    {"v",    P_VOLUME,     NULL},
    {"w",    P_STRING_OPT, NULL},
    {"x",    P_INCEXC,     NULL},
    {"y",    P_NONE,       NULL},
    {NULL,   P_NONE,       NULL}
};

static int ci_starts(const char *hay, const char *needle, size_t *consumed)
{
    size_t i = 0;
    while (needle[i]) {
        if (!hay[i]) return 0;
        if (tolower((unsigned char)hay[i]) != tolower((unsigned char)needle[i]))
            return 0;
        i++;
    }
    *consumed = i;
    return 1;
}

static const struct switch_def *find_switch(const char *body, size_t *plen)
{
    const struct switch_def *best = NULL;
    size_t best_len = 0;
    for (const struct switch_def *s = SWITCHES; s->prefix; s++) {
        size_t n;
        if (ci_starts(body, s->prefix, &n) && n > best_len) {
            best = s;
            best_len = n;
        }
    }
    if (best) *plen = best_len;
    return best;
}

/* -ai / -ax / -i / -x tail parser.
 *   0 OK  1 "Too short"  2 "Incorrect postfix" */
static int parse_incexc(const char *p)
{
    if ((*p == 'r' || *p == 'R')) {
        p++;
        if (*p == '-' || *p == '0') p++;
    }
    if ((*p == 'm' || *p == 'M')) {
        p++;
        if (*p == '-' || *p == '2') p++;
    }
    if ((*p == 'w' || *p == 'W')) {
        p++;
        if (*p == '-') p++;
    }
    if (*p == 0) return 1;
    if (*p != '@' && *p != '!') return 2;
    return 0;
}

static int parse_update(const char *p)
{
    if (*p == '-') p++;
    while (*p) {
        char c = (char)tolower((unsigned char)*p);
        if (c == '!') return 0; /* rest is new archive name */
        if (c == 'p' || c == 'q' || c == 'r' || c == 'x' || c == 'y' || c == 'z') {
            p++;
            /* accept digits/labels until the next state letter or '!' */
            while (*p && *p != '!') {
                char d = (char)tolower((unsigned char)*p);
                if (d == 'p' || d == 'q' || d == 'r' || d == 'x' ||
                    d == 'y' || d == 'z')
                    break;
                p++;
            }
        } else {
            return 2;
        }
    }
    return 0;
}

static int parse_volume(const char *p)
{
    if (!*p) return 1;
    const char *start = p;
    while (*p && isdigit((unsigned char)*p)) p++;
    if (p == start) return 2;
    if (*p) {
        char c = (char)tolower((unsigned char)*p);
        if (c != 'b' && c != 'k' && c != 'm' && c != 'g') return 2;
        if (p[1] != 0) return 2;
    }
    return 0;
}

static int parse_bs(const char *p)
{
    if (!p[0]) return 1;
    if (!p[1]) return 1;
    if (p[2]) return 3;
    char a = (char)tolower((unsigned char)p[0]);
    char b = p[1];
    if (a != 'o' && a != 'e' && a != 'p') return 2;
    if (b != '0' && b != '1' && b != '2') return 2;
    return 0;
}

static int parse_bb(const char *p)
{
    if (!*p) return 0;
    if (p[1]) return 3;
    if (*p < '0' || *p > '3') return 2;
    return 0;
}

/* Parse a single switch.  Returns 0 on success, or EXIT_CMDLINE on failure
 * after emitting the appropriate error message. */
static int parse_switch(const char *arg)
{
    const char *body = arg + 1;

    /* Detect bare "-" and long-form "--foo" (the "--" alone case is handled
     * by the caller before we get here). */
    if (*body == 0 || *body == '-') {
        return switch_error("Unknown switch:", arg);
    }

    /* Help prefix: one of h/H/? followed by anything extra → "Too long". */
    if (body[0] == '?' || body[0] == 'h' || body[0] == 'H') {
        if (body[1] != 0)
            return switch_error("Too long switch:", arg);
        /* Bare -h / -? would have been caught earlier by is_help_arg(). */
        return switch_error("Too long switch:", arg);
    }

    size_t plen = 0;
    const struct switch_def *s = find_switch(body, &plen);
    if (!s) {
        return switch_error("Unknown switch:", arg);
    }
    const char *tail = body + plen;

    switch (s->kind) {
    case P_NONE:
        if (*tail) return switch_error("Too long switch:", arg);
        return 0;

    case P_MINUS:
        if (*tail == 0) return 0;
        if (tail[0] == '-' && tail[1] == 0) return 0;
        return switch_error("Too long switch:", arg);

    case P_MINUS_ZERO:
        if (*tail == 0) return 0;
        if (tail[0] == '-' && tail[1] == 0) return 0;
        if (tail[0] == '0' && tail[1] == 0) return 0;
        return switch_error("Too long switch:", arg);

    case P_CHAR_SET: {
        if (*tail == 0) return switch_error("Too short switch:", arg);
        if (tail[1] != 0) return switch_error("Too long switch:", arg);
        char c = (char)tolower((unsigned char)*tail);
        if (!strchr(s->valid_chars, c))
            return switch_error("Incorrect switch postfix:", arg);
        return 0;
    }

    case P_STRING_REQ:
        if (*tail == 0) return switch_error("Too short switch:", arg);
        return 0;

    case P_STRING_OPT:
        return 0;

    case P_INCEXC: {
        int r = parse_incexc(tail);
        if (r == 1) return switch_error("Too short switch:", arg);
        if (r == 2) return switch_error("Incorrect switch postfix:", arg);
        return 0;
    }

    case P_UPDATE: {
        int r = parse_update(tail);
        if (r == 2) return switch_error("Incorrect switch postfix:", arg);
        return 0;
    }

    case P_VOLUME: {
        int r = parse_volume(tail);
        if (r == 1) return switch_error("Too short switch:", arg);
        if (r == 2) return switch_error("Incorrect switch postfix:", arg);
        return 0;
    }

    case P_BS: {
        int r = parse_bs(tail);
        if (r == 1) return switch_error("Too short switch:", arg);
        if (r == 2) return switch_error("Incorrect switch postfix:", arg);
        if (r == 3) return switch_error("Too long switch:", arg);
        return 0;
    }

    case P_BB: {
        int r = parse_bb(tail);
        if (r == 2) return switch_error("Incorrect switch postfix:", arg);
        if (r == 3) return switch_error("Too long switch:", arg);
        return 0;
    }

    case P_SCC:
        if (*tail == 0) return switch_error("Too short switch:", arg);
        return 0;

    case P_SCS:
        return 0;
    }
    return 0;
}

/* --------------------------------------------------------------------- */
/* Commands                                                              */
/* --------------------------------------------------------------------- */

static int is_known_command(const char *cmd)
{
    static const char *const cmds[] = {
        "a", "b", "d", "e", "h", "i", "l", "rn", "t", "u", "x", NULL
    };
    for (size_t i = 0; cmds[i]; i++)
        if (strcmp(cmds[i], cmd) == 0) return 1;
    return 0;
}

static int command_needs_archive(const char *cmd)
{
    /* b (benchmark), i (info), h (hash) do not take an archive. */
    return !(strcmp(cmd, "b") == 0 ||
             strcmp(cmd, "i") == 0 ||
             strcmp(cmd, "h") == 0);
}

/* --------------------------------------------------------------------- */
/* Fatal "no such file" emitter (exit 2)                                 */
/* --------------------------------------------------------------------- */

static int fatal_errno(const char *path, int err)
{
    const char *estr = strerror(err);
    fprintf(stderr, "\nERROR: errno=%d : %s\n%s\n\n\n", err, estr, path);
    fprintf(stderr, "\nSystem ERROR:\nerrno=%d : %s\n", err, estr);
    fflush(stderr);
    return EXIT_FATAL;
}

/* --------------------------------------------------------------------- */
/* Main                                                                  */
/* --------------------------------------------------------------------- */

int main(int argc, char **argv)
{
    setlocale(LC_ALL, "");

    /* Pass 1: if a help switch appears anywhere before "--", display help. */
    int saw_dd = 0;
    for (int i = 1; i < argc; i++) {
        if (!saw_dd && strcmp(argv[i], "--") == 0) { saw_dd = 1; continue; }
        if (!saw_dd && is_help_arg(argv[i])) {
            write_banner();
            write_usage();
            return EXIT_OK;
        }
    }

    /* No arguments at all ⇒ same as help. */
    if (argc < 2) {
        write_banner();
        write_usage();
        return EXIT_OK;
    }

    /* Pass 2: parse switches, collect positionals, detect duplicates. */
    saw_dd = 0;
    const char **positionals = calloc((size_t)argc, sizeof(char *));
    int npos = 0;
    int seen_y = 0;

    for (int i = 1; i < argc; i++) {
        const char *a = argv[i];
        if (!saw_dd && strcmp(a, "--") == 0) { saw_dd = 1; continue; }
        if (!saw_dd && a[0] == '-') {
            int rc = parse_switch(a);
            if (rc) { free(positionals); return rc; }
            if (a[1] == 'y' && a[2] == 0) {
                if (seen_y) {
                    free(positionals);
                    return switch_error("Multiple instances for switch:", a);
                }
                seen_y = 1;
            }
            continue;
        }
        positionals[npos++] = a;
    }

    if (npos == 0) {
        free(positionals);
        return command_error("The command must be specified", NULL);
    }

    const char *cmd = positionals[0];
    if (!is_known_command(cmd)) {
        const char *detail = cmd;
        free(positionals);
        return command_error("Unsupported command:", detail);
    }

    if (command_needs_archive(cmd) && npos < 2) {
        free(positionals);
        return command_error("Cannot find archive name", NULL);
    }

    /* We have enough to claim success at the parse level.  Emit the
     * banner and then fail gracefully since no archive engine exists. */
    write_banner();

    if (command_needs_archive(cmd)) {
        const char *arch = positionals[1];
        if (access(arch, F_OK) != 0) {
            int err = errno ? errno : ENOENT;
            free(positionals);
            return fatal_errno(arch, err);
        }
    }

    free(positionals);
    /* Without an archive engine we cannot fulfil the request; emit a
     * generic fatal error so we never silently lie about success. */
    fputs("\nSystem ERROR:\nUnsupported\n", stderr);
    return EXIT_FATAL;
}
EOF
./compile.sh && echo "Compiled OK"

