 * 7-Zip compatible command-line driver (partial reimplementation).
 *
 * This binary reproduces the observable command-line behaviour of the 7za
 * front-end: the banner, the usage help, and the switch/command parser
 * error messages.  It does *not* implement any archive engine, so actual
 * archive operations cannot succeed; they fail with the same style of
 * "System ERROR" messages the real tool would emit for a missing file.
 */

#define _GNU_SOURCE
#include <ctype.h>
#include <errno.h>
