static long query_threads(void)
{
    long n = sysconf(_SC_NPROCESSORS_ONLN);
    return (n < 1) ? 1 : n;
}

static long query_open_max(void)
{
    struct rlimit rl;
    if (getrlimit(RLIMIT_NOFILE, &rl) == 0 && rl.rlim_cur != RLIM_INFINITY)
        return (long)rl.rlim_cur;
    long n = sysconf(_SC_OPEN_MAX);
    return (n < 0) ? 1024 : n;
}

static void write_banner(void)
{
    /* 7-Zip always reports locale=C.UTF-8 on our reference platform,
     * regardless of LC_ALL/LANG, so we do the same. */
    fputc('\n', stdout);
    fputs("7-Zip (a) 26.00 (x64) : Copyright (c) 1999-2026 Igor Pavlov : 2026-02-12\n",
          stdout);
    fprintf(stdout, " 64-bit locale=C.UTF-8 Threads:%ld OPEN_MAX:%ld\n",
            query_threads(), query_open_max());
