/* --------------------------------------------------------------------- */
/* Error emitters                                                        */
/* --------------------------------------------------------------------- */

/* Switch parser errors do *not* emit the banner. */
static int switch_error(const char *title, const char *detail)
{
    fputs("\n\nCommand Line Error:\n", stderr);
    fputs(title, stderr);
    fputc('\n', stderr);
    fputs(detail, stderr);
    fputc('\n', stderr);
    fflush(stderr);
    return EXIT_CMDLINE;
}

/* Command / archive related errors emit the banner first. */
static int command_error(const char *title, const char *detail)
{
    write_banner();
    fputs("\n\nCommand Line Error:\n", stderr);
    fputs(title, stderr);
    fputc('\n', stderr);
    if (detail) {
        fputs(detail, stderr);
        fputc('\n', stderr);
    }
    fflush(stderr);
    return EXIT_CMDLINE;
}

/* --------------------------------------------------------------------- */
/* Helpers                                                               */
/* --------------------------------------------------------------------- */

static int ci_eq(const char *a, const char *b)
{
    while (*a && *b) {
        if (tolower((unsigned char)*a) != tolower((unsigned char)*b))
            return 0;
        a++; b++;
    }
    return *a == 0 && *b == 0;
}

static int is_help_arg(const char *arg)
{
    /* -h / -H (exactly), -? (exactly), --help (any case). */
    if (arg[0] != '-') return 0;
    if ((arg[1] == 'h' || arg[1] == 'H') && arg[2] == 0) return 1;
    if (arg[1] == '?' && arg[2] == 0) return 1;
    if (arg[1] == '-' && ci_eq(arg + 2, "help")) return 1;
    return 0;
}

/* --------------------------------------------------------------------- */
/* Switch grammar                                                        */
